arguments.command:
bash -lc 'cd /src/wasm3 && perl -0777 -pe "s/M3Compiler compiler = GetOpInfo \(i_opcode\)\->compiler;
_throwif \(m3Err_noCompiler, not compiler\);

_\s*\(\*\s*compiler\) \(o, i_opcode\);

\s*o->previousOpcode = i_opcode;/const M3OpInfo* opInfo = GetOpInfo (i_opcode);
if (opInfo == NULL || opInfo->compiler == NULL) {
    o->previousOpcode = i_opcode;
} else {
    M3Compiler compiler = opInfo->compiler;
    _throwif (m3Err_noCompiler, not compiler);

    ((* compiler) (o, i_opcode));

    o->previousOpcode = i_opcode;
}/s" source/m3_compile.c && echo PATCHED'

bash -lc 'cd /src/wasm3 && perl -0777 -pe "s/const M3OpInfo\* opInfo = GetOpInfo \(i_opcode\)\;
\s*_throwif \(m3Err_noCompiler, opInfo == NULL \|\| opInfo->compiler == NULL\);/const M3OpInfo* opInfo = GetOpInfo (i_opcode);
    if (opInfo == NULL || opInfo->compiler == NULL) {
        _throw (ErrorCompile (m3Err_unknownOpcode, o, "extended opcode 0x%x not available", i_opcode));
    }/s" source/m3_compile.c -i'
